            principal = principal.subtract(down);
            dues.add(issueDate);
            schedule.add(new Instalment(0, issueDate, down, zero(), down, principal));
        }
        int downs = dues.size();
        for (int k = 1; k <= instalments; k++) {
            dues.add(issueDate == null ? null : issueDate.plusMonths(k));
